<style>
.media-library{max-width:1580px;margin:auto;padding:28px 30px 40px;color:var(--theme-header-text-color)}
.media-library-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.media-library-heading h1{font-size:27px;font-weight:650;letter-spacing:-.035em;margin:0}.media-library-heading p{font-size:13px;color:var(--theme-muted-text-color);margin:7px 0 0}
.media-search-toolbar{display:flex;align-items:flex-end;gap:12px;padding:18px;background:var(--theme-surface-base);border:1px solid var(--theme-card-border-color);border-radius:12px}.media-search-toolbar>div{min-width:135px}.media-search-toolbar .media-search-query{flex:1;min-width:180px}.media-search-toolbar>button{flex-shrink:0;height:40px}.media-search-toolbar label,.media-import-folder label{font-size:12px}.media-search-toolbar select{max-width:260px}
.media-library-hint,.media-results-heading,.media-search-loading{font-size:12px;color:var(--theme-muted-text-color);margin:16px 0}.media-results-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:22px 0 14px}.media-results-heading strong{color:var(--theme-header-text-color);font-weight:600}.media-result-source{font-size:11px}
.media-search-error{display:flex;align-items:center;gap:10px;padding:14px 16px;margin-top:18px;border:1px solid #f2b3a9;border-radius:9px;background:var(--theme-surface-base);color:#b13f32;font-size:13px}
.media-search-empty{text-align:center;padding:70px 20px}.media-empty-icon{display:inline-grid;place-items:center;width:58px;height:58px;border-radius:15px;background:var(--theme-surface-subtle);color:var(--theme-accent);font-size:23px}.media-search-empty h2{font-size:20px;font-weight:600;margin:20px 0 8px}.media-search-empty p{font-size:13px;color:var(--theme-muted-text-color)}.media-search-suggestions{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-top:22px}.media-search-suggestions button{border:1px solid var(--theme-border-color);background:var(--theme-surface-base);padding:8px 15px;border-radius:8px;font-size:12px}
.media-results-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.media-result-card{min-width:0;border:1px solid var(--theme-card-border-color);border-radius:11px;overflow:hidden;background:var(--theme-surface-base)}.media-result-card.is-selected{border-color:var(--theme-accent);box-shadow:0 0 0 1px var(--theme-accent)}.media-result-image{position:relative;aspect-ratio:4/3;background:var(--theme-surface-soft)}.media-preview-trigger{width:100%;height:100%;display:block}.media-preview-trigger img{width:100%;height:100%;object-fit:cover}.media-source-badge,.media-saved-badge{position:absolute;left:10px;top:10px;padding:4px 8px;border-radius:6px;background:rgba(255,255,255,.94);color:#314338;font-size:10px;font-weight:600;text-transform:capitalize;pointer-events:none}.media-saved-badge{top:auto;bottom:10px;display:flex;gap:5px;align-items:center}.media-result-check{position:absolute;right:10px;top:10px;background:var(--theme-surface-base);border-radius:6px;padding:5px;display:flex}.media-result-check label:has(input:focus-visible){outline:2px solid var(--theme-accent);outline-offset:4px}.media-video-play{position:absolute;inset:0;display:grid;place-items:center;color:white;text-shadow:0 2px 7px #000;font-size:24px;pointer-events:none}.media-result-info{display:flex;flex-direction:column;gap:5px;padding:13px 14px}.media-result-info strong{font-size:13px;font-weight:600;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.media-result-info>span{font-size:11px;color:var(--theme-muted-text-color)}.media-item-error{font-size:12px;color:#b13f32;margin:0;padding:10px 14px}.media-load-more{text-align:center;padding:25px}
.media-import-bar{position:sticky;bottom:16px;z-index:35;display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin-top:22px;margin-right:56px;padding:16px 20px;background:var(--theme-surface-base);border:1px solid var(--theme-accent);border-radius:12px;box-shadow:0 6px 24px rgba(0,0,0,.09)}.media-import-summary{display:flex;align-items:center;gap:12px;flex:1;font-size:13px}.media-import-summary button{color:var(--theme-accent);text-decoration:underline;font-size:12px}.media-import-summary>span{font-size:12px;color:var(--theme-muted-text-color)}.media-import-folder{width:260px}.media-import-failures{flex-basis:100%;font-size:12px;color:#b13f32;max-height:100px;overflow:auto}
.media-preview-overlay{position:fixed;inset:0;z-index:200;display:flex;align-items:center;justify-content:center;padding:24px;background:rgba(10,22,17,.65)}.media-preview-dialog{width:min(900px,100%);max-height:92dvh;overflow:auto;border-radius:14px;background:var(--theme-surface-base);box-shadow:0 20px 70px rgba(0,0,0,.2)}.media-preview-dialog header,.media-preview-dialog footer{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 22px}.media-preview-dialog h2{font-size:17px;font-weight:600}.media-preview-dialog header p{font-size:12px;color:var(--theme-muted-text-color);margin-top:4px}.media-preview-dialog header button{width:36px;height:36px;border:1px solid var(--theme-border-color);border-radius:8px}.media-preview-stage{display:flex;justify-content:center;align-items:center;background:#111b16;min-height:180px}.media-preview-stage img,.media-preview-stage video{max-height:62dvh;max-width:100%;object-fit:contain}.media-preview-dialog footer a{font-size:12px;color:var(--theme-accent)}
@media(min-width:1600px){.media-results-grid{grid-template-columns:repeat(5,minmax(0,1fr))}}
@media(max-width:1199px){.media-search-toolbar{flex-wrap:wrap}.media-search-toolbar .media-search-query{flex-basis:100%}.media-search-toolbar>div{flex:1}.media-results-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:639px){.media-library{padding:20px 14px 30px}.media-library-heading{align-items:flex-start;gap:12px}.media-library-heading h1{font-size:23px}.media-library-heading p{font-size:12px;line-height:1.6}.media-library-heading>a{white-space:nowrap;font-size:11px!important;padding:8px!important}.media-search-toolbar{padding:13px;gap:10px}.media-search-toolbar>div{min-width:0;flex-basis:calc(50% - 10px)}.media-search-toolbar select{max-width:100%}.media-search-toolbar>button{width:100%}.media-results-heading{margin-top:17px}.media-results-heading>span{display:none}.media-results-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.media-result-info{padding:10px}.media-result-info strong{font-size:12px}.media-result-image{aspect-ratio:1}.media-search-empty{padding:40px 8px}.media-import-bar{bottom:70px;margin-right:0;padding:12px;gap:12px}.media-import-summary{flex-basis:100%}.media-import-folder{flex:1;min-width:0}.media-preview-overlay{padding:10px}.media-preview-dialog header,.media-preview-dialog footer{padding:14px}.media-preview-dialog footer{flex-wrap:wrap}}
</style>
